def tribonacci(n):
    if n == 0:
        return 0
    if n <= 2:
        return 1
    a, b, c = 0, 1, 1                                      # T0, T1, T2
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c                             # slide the window forward
    return c

